import sys, os, itertools
root = sys.argv[1]
files = sorted(f for f in os.listdir(root) if f.endswith(".py"))
norm = {}
for f in files:
    with open(os.path.join(root, f), encoding="utf-8") as fh:
        lines = [ln.strip() for ln in fh.read().splitlines()]
    norm[f] = [ln for ln in lines if ln != ""]

def blocks(a, b, minlen=5):
    # longest contiguous common runs of normalized lines
    best = []
    la, lb = len(a), len(b)
    for i in range(la):
        for j in range(lb):
            k = 0
            while i + k < la and j + k < lb and a[i+k] == b[j+k]:
                k += 1
            if k >= minlen:
                best.append((i, j, k))
    # dedupe to maximal runs
    out = []
    for i, j, k in best:
        if any(ii <= i and i+k <= ii+kk for ii, jj, kk in best if (ii, jj, kk) != (i, j, k)):
            continue
        out.append((i, j, k))
    return out

for fa, fb in itertools.combinations(files, 2):
    bs = blocks(norm[fa], norm[fb])
    for i, j, k in bs:
        print(f"{fa}:norm-line-{i+1}-{i+k} {fb}:norm-line-{j+1}-{j+k} len={k}")
print("files:", files)
